#!/usr/bin/env node
// Builds supabase/functions/forge-witness-verify/core.bundle.js from web/lib/projections/pregameCapture/witnessEdgeCore.ts
// (and only its import closure), reproducibly. The release id baked into every signed verdict is the sha256 over the
// bundle's sorted input paths and bytes, so an auditor can rebuild from a commit and compare. Usage, from the repo root:
//   node tasks/artifacts/forge-witness-signed-2026-11-19/build-edge-bundle.mjs [--check]
// --check rebuilds in memory and exits 1 if the committed bundle or manifest differ.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
const web = join(root, "web");
const esbuild = createRequire(join(web, "package.json"))("esbuild");
const entry = join(web, "lib/projections/pregameCapture/witnessEdgeCore.ts");
const outDir = join(root, "supabase/functions/forge-witness-verify");
const shim = join(root, "tasks/artifacts/forge-witness-signed-2026-11-19/buffer-shim.mjs");
const base = { entryPoints: [entry], bundle: true, format: "esm", platform: "neutral", target: "es2022", write: false,
  external: ["node:*"], inject: [shim], legalComments: "none", charset: "utf8", sourcemap: false, logLevel: "silent" };

const first = await esbuild.build({ ...base, metafile: true, define: { __WITNESS_RELEASE__: '""' } });
const inputs = Object.keys(first.metafile.inputs).map(p => relative(root, resolve(process.cwd(), p))).sort();
const release = createHash("sha256");
for (const path of inputs) release.update(path + "\0").update(readFileSync(join(root, path))).update("\0");
const id = release.digest("hex");
const built = await esbuild.build({ ...base, define: { __WITNESS_RELEASE__: JSON.stringify(id) } });
const header = `// GENERATED by tasks/artifacts/forge-witness-signed-2026-11-19/build-edge-bundle.mjs from ${relative(root, entry)}; do not edit.\n` +
  `// release ${id}\n`;
const bundle = header + built.outputFiles[0].text;
const manifest = JSON.stringify({ release: id, bundleSha256: createHash("sha256").update(bundle).digest("hex"), inputs }, null, 1) + "\n";
if (process.argv.includes("--check")) {
  const same = readFileSync(join(outDir, "core.bundle.js"), "utf8") === bundle && readFileSync(join(outDir, "bundle-manifest.json"), "utf8") === manifest;
  console.log(same ? `bundle up to date: release ${id}` : "bundle OUT OF DATE");
  process.exit(same ? 0 : 1);
}
writeFileSync(join(outDir, "core.bundle.js"), bundle);
writeFileSync(join(outDir, "bundle-manifest.json"), manifest);
console.log(`release ${id}; ${inputs.length} inputs; bundle ${bundle.length} bytes`);
